// Сводка Заявки для группы Заказчика. Простой текст: без parse_mode нечего экранировать.
// needs_human — Передача человеку: причина, Беседа и кнопка «Вернуть ассистенту».
const lead = $json;
const handoff = lead.status === 'needs_human';
const field = (label, value) => `${label}: ${value ?? '—'}`;
const clip = (text) => (text.length > 300 ? `${text.slice(0, 300)}…` : text);
const lines = [
  handoff ? 'Нужен человек: Ассистент передал Беседу' : 'Новая заявка',
  field('Заказчик', lead.company_name),
  field('Клиент', `${lead.channel} ${lead.sender_id}`),
  ...(handoff ? [field('Причина', lead.handoff_reason)] : []),
  field('Намерение', lead.intent),
  field('Имя', lead.name),
  field('Контакт', lead.contact),
  field('Услуга', lead.service),
  field('Описание', lead.description),
  field('Желаемая дата', lead.desired_date),
];
if (handoff) {
  lines.push('', 'Беседа:');
  for (const message of lead.history) {
    lines.push(`${message.direction === 'in' ? 'Клиент' : 'Ассистент'}: ${clip(message.text)}`);
  }
}
// callback_data «<действие>:<lead_id>» разбирает workflow telegram-callback.
const close = { text: 'Закрыть', callback_data: `close:${lead.lead_id}` };
const resume = { text: 'Вернуть ассистенту', callback_data: `resume:${lead.lead_id}` };
return {
  chat_id: lead.telegram_chat_id,
  text: lines.join('\n'),
  reply_markup: { inline_keyboard: [handoff ? [resume, close] : [close]] },
};
